	void endpointSyntaxPolicyIsInstalledBeforePreparingQuery() throws Exception {
		DefaultQueryRequestHandler handler = new DefaultQueryRequestHandler(mock(RepositoryResolver.class));
		RepositoryConnection connection = mock(RepositoryConnection.class);
		when(connection.getQueryParseOptions()).thenReturn(QueryParseOptions.DEFAULT);
		TupleQuery query = mock(TupleQuery.class);
		String source = "SELECT ?node WHERE { VALUES ?node { <_:id> } }";
		when(connection.prepareQuery(eq(QueryLanguage.SPARQL), eq(source), any())).thenReturn(query);
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.setAttribute(QueryParseOptions.class.getName(), QueryParseOptions.STRICT);
		handler.getQuery(request, connection, source);
		org.mockito.InOrder order = org.mockito.Mockito.inOrder(connection);
		order.verify(connection).setQueryParseOptions(QueryParseOptions.STRICT);
		order.verify(connection).prepareQuery(QueryLanguage.SPARQL, source, null);
	}
